package provider
import("context";"encoding/json";"io";"net/http";"strings";"testing";"github.com/hashicorp/terraform-plugin-framework/resource";"github.com/hashicorp/terraform-plugin-framework/tfsdk";"github.com/hashicorp/terraform-plugin-framework/types";"github.com/hashicorp/terraform-plugin-go/tftypes")
type compositeHTTP struct{t *testing.T;calls int;parent string}
func(h *compositeHTTP)Do(req *http.Request)(*http.Response,error){h.calls++;expected:="/organizations/a%2Fb/things";if req.Method!="POST"{expected+="/child%2Fid"};if req.URL.EscapedPath()!=expected{h.t.Fatalf("wrong identity path %s",req.URL.EscapedPath())};if req.Method=="POST"||req.Method=="PATCH"{var body map[string]any;if json.NewDecoder(req.Body).Decode(&body)!=nil||len(body)!=0{h.t.Fatal("parent leaked into body")}};body,_:=json.Marshal(map[string]string{"id":"child/id","organizationId":h.parent});return &http.Response{StatusCode:200,Header:http.Header{},Body:io.NopCloser(strings.NewReader(string(body)))},nil}
func TestCompositeLifecycleAndImport(t *testing.T){ctx:=context.Background();driver:=&compositeHTTP{t:t,parent:"a/b"};r:=&ThingResource{client:&apiClient{baseURL:"https://example.test",httpClient:driver}};schemaResponse:=resource.SchemaResponse{};r.Schema(ctx,resource.SchemaRequest{},&schemaResponse);schema:=schemaResponse.Schema
 plan:=tfsdk.Plan{Schema:schema,Raw:tftypes.NewValue(schema.Type().TerraformType(ctx),nil)};model:=ThingResourceModel{ID:types.StringUnknown(),OrganizationId:types.StringValue("a/b")};if d:=plan.Set(ctx,&model);d.HasError(){t.Fatal(d)};created:=resource.CreateResponse{State:tfsdk.State{Schema:schema,Raw:tftypes.NewValue(schema.Type().TerraformType(ctx),nil)}};r.Create(ctx,resource.CreateRequest{Plan:plan},&created);if created.Diagnostics.HasError(){t.Fatal(created.Diagnostics)};if d:=created.State.Get(ctx,&model);d.HasError(){t.Fatal(d)};parts,err:=ThingResourceParseIdentity(model.ID.ValueString());if err!=nil||parts["org"]!="a/b"||parts["thingId"]!="child/id"{t.Fatal("composite identity lost",err)}
 updated:=resource.UpdateResponse{State:created.State};r.Update(ctx,resource.UpdateRequest{Plan:plan,State:created.State},&updated);if updated.Diagnostics.HasError(){t.Fatal(updated.Diagnostics)};read:=resource.ReadResponse{State:updated.State};r.Read(ctx,resource.ReadRequest{State:updated.State},&read);if read.Diagnostics.HasError(){t.Fatal(read.Diagnostics)};deleted:=resource.DeleteResponse{State:read.State};r.Delete(ctx,resource.DeleteRequest{State:read.State},&deleted);if deleted.Diagnostics.HasError()||!deleted.State.Raw.IsNull(){t.Fatal("delete failed",deleted.Diagnostics)}
 imported:=resource.ImportStateResponse{State:tfsdk.State{Schema:schema,Raw:tftypes.NewValue(schema.Type().TerraformType(ctx),nil)}};r.ImportState(ctx,resource.ImportStateRequest{ID:"{ \"thingId\":\"child/id\", \"org\":\"a/b\" }"},&imported);if imported.Diagnostics.HasError(){t.Fatal(imported.Diagnostics)};read=resource.ReadResponse{State:imported.State};r.Read(ctx,resource.ReadRequest{State:imported.State},&read);if read.Diagnostics.HasError(){t.Fatal(read.Diagnostics)}
 driver.parent="changed";failed:=resource.CreateResponse{State:tfsdk.State{Schema:schema,Raw:tftypes.NewValue(schema.Type().TerraformType(ctx),nil)}};r.Create(ctx,resource.CreateRequest{Plan:plan},&failed);if !failed.Diagnostics.HasError()||!failed.State.Raw.IsFullyKnown(){t.Fatal("parent mismatch not recoverable")};if d:=failed.State.Get(ctx,&model);d.HasError(){t.Fatal(d)};parts,err=ThingResourceParseIdentity(model.ID.ValueString());if err!=nil||parts["org"]!="a/b"{t.Fatal("wrong parent echo replaced managed identity")}
 before:=driver.calls;model.OrganizationId=types.StringValue("");if d:=plan.Set(ctx,&model);d.HasError(){t.Fatal(d)};failed=resource.CreateResponse{State:created.State};r.Create(ctx,resource.CreateRequest{Plan:plan},&failed);if !failed.Diagnostics.HasError()||driver.calls!=before{t.Fatal("empty parent sent")}
 for _,id:=range []string{"{}","{\"org\":\"a\",\"thingId\":\"\"}","{\"org\":\"a\",\"org\":\"b\",\"thingId\":\"c\"}","{\"org\":\"a\",\"thingId\":\"c\"} null"}{if _,err:=ThingResourceParseIdentity(id);err==nil{t.Fatal("invalid composite accepted")}}
}
